import{_ as o,c as r,o as d,a2 as n}from"./chunks/framework.CHomSxuB.js";const l=JSON.parse('{"title":"1 · V5 信号体系与考决","description":"","frontmatter":{},"headers":[],"relativePath":"足球信号雷达/1-V5信号体系与考决.md","filePath":"足球信号雷达/1-V5信号体系与考决.md"}'),s={name:"足球信号雷达/1-V5信号体系与考决.md"};function g(p,t,u,q,e,a){return d(),r("div",null,t[0]||(t[0]=[n('<h1 id="_1-·-v5-信号体系与考决" tabindex="-1">1 · V5 信号体系与考决 <a class="header-anchor" href="#_1-·-v5-信号体系与考决" aria-label="Permalink to &quot;1 · V5 信号体系与考决&quot;">​</a></h1><blockquote><p>状态：<strong>V5 四信号冻结后 OOS 观测中（截至 2026-11-01）</strong> 口径：命中 = 不败方向命中；超额 = 命中率 − 赔率隐含概率（去水）</p></blockquote><p><a href="/足球信号雷达/">返回 足球信号雷达 首页</a></p><hr><h2 id="一、v5-是什么" tabindex="-1">一、V5 是什么 <a class="header-anchor" href="#一、v5-是什么" aria-label="Permalink to &quot;一、V5 是什么&quot;">​</a></h2><p>老一代&quot;裁判层&quot;（多路亚盘/大小球/欧赔信号汇总成单一裁定）在真实回放中被证伪为负期望后（见 <a href="./2-历史战线与下注层废弃.html">2-历史战线与下注层废弃</a>）， 项目 2026-08 重建为 <strong>V5：只保留&quot;方向级&quot;欧赔信号</strong>——不预测比分、不猜庄家意图，只回答一个问题： <strong>这个市场的钱在往哪边走，跟不跟。</strong></p><p>V5 的信号全部是<strong>结构规则</strong>（由赔率轨迹的形态触发），不是机器学习——定稿后禁止在同一段历史上再挖阈值，防过拟合。</p><h2 id="二、2026-08-21-冻结考决-5-规则-→-4-活-1-死" tabindex="-1">二、2026-08-21 冻结考决：5 规则 → 4 活 1 死 <a class="header-anchor" href="#二、2026-08-21-冻结考决-5-规则-→-4-活-1-死" aria-label="Permalink to &quot;二、2026-08-21 冻结考决：5 规则 → 4 活 1 死&quot;">​</a></h2><p>一周样本外（OOS）考决后，信号体系定稿。判决表（考决段 OOS 实测）：</p><table tabindex="0"><thead><tr><th>信号</th><th>语义（脱敏）</th><th>OOS 命中 (n)</th><th>超额</th><th>EV/注</th><th>判决</th></tr></thead><tbody><tr><td><strong>SSS_VETO_H</strong></td><td>定盘星背离：强热门区里大众盘压主、职业盘反向抬主 → 跟职业防守方向（客不败）</td><td>86.7% (15 场)</td><td>+40.0pp</td><td>+93.7%</td><td>✅ 存活（样本偏小）</td></tr><tr><td><strong>SSS_GLOBAL_DRIFT</strong></td><td>弱势弃守（客向）：主队弱势 + 主胜赔率被市场持续抬升 → 客不败</td><td>76.6% (171 场)</td><td>+22.0pp</td><td>+35.0%</td><td>✅ 存活</td></tr><tr><td><strong>SSS_HOME_DRIFT</strong></td><td>弱势弃守（主向）：客队弱势 + 客胜赔率被市场持续抬升 → 主不败</td><td>73.6% (246 场)</td><td>+20.5pp</td><td>+32.1%</td><td>✅ 存活</td></tr><tr><td><strong>A_UNDERDOG_QUAKE</strong></td><td>准冷门震荡：弱势方赔率大幅下滑（资金涌入）→ 弱队不败倾向</td><td>61.3% (80 场)</td><td>+28.2pp</td><td>+70.3%</td><td>✅ 存活</td></tr><tr><td>A_DRAW_MAGNET</td><td>低平赔·平局引力</td><td>35.7% (28 场)</td><td>+3.7pp</td><td>+1.5%</td><td>❌ 淘汰（无 edge）</td></tr></tbody></table><p>考决中同步处死的两个&quot;虚高信号&quot;——<strong>这是本系列最有价值的部分</strong>：</p><ol><li><strong>赔率版定盘星（SSS_VETO 原版）</strong>：样本段 82% 命中 → OOS 掉到 54.5%（−27.5pp，EV −7.1%）。 典型的多重检验虚高：在历史里&quot;试&quot;出来的好规则，一到样本外就打回原形。其 <code>Δlog + 强热门区</code> 变体（即上面存活的 VETO_H）被救活。</li><li><strong>升级逻辑（概率流向 → 直接看主胜/客胜）</strong>：比赔率版低 6~7pp，且 OOS 分歧场次对旧版全错——<strong>确认负贡献，禁用</strong>。</li></ol><h2 id="三、冻结纪律" tabindex="-1">三、冻结纪律 <a class="header-anchor" href="#三、冻结纪律" aria-label="Permalink to &quot;三、冻结纪律&quot;">​</a></h2><ul><li>上述 4 条定稿后<strong>不再修改、不再挖阈值</strong>（同段挖参 = 自欺）；</li><li>判据线：<strong>SSS_VETO 需累计 50+ 场且命中率 &gt;70% 才谈转正</strong>；QUAKE 的两家版 vs 赔率版之争交给样本说话；</li><li>真实生产 edge 应低于考决数字（考决用最终态赔率快照，与赛前实时信号存在时点漂移——08-18 实测同一场赛前/赛后重跑信号会变）。</li></ul><h2 id="四、当前-oos-状态-每日对账-滚动窗口自-2026-08-15-起" tabindex="-1">四、当前 OOS 状态（每日对账，滚动窗口自 2026-08-15 起） <a class="header-anchor" href="#四、当前-oos-状态-每日对账-滚动窗口自-2026-08-15-起" aria-label="Permalink to &quot;四、当前 OOS 状态（每日对账，滚动窗口自 2026-08-15 起）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>信号</th><th>n</th><th>命中</th><th>赔率隐含</th><th>超额</th><th>判据进度</th></tr></thead><tbody><tr><td>SSS_HOME_DRIFT</td><td>2611</td><td>82.2%</td><td>79.0%</td><td><strong>+3.2pp</strong></td><td>⚠️ 观察（CI 排除 0 但未达 5pp；<strong>10-30 同价位口径下增量 edge 仅 +0.9pp</strong>）</td></tr><tr><td>SSS_GLOBAL_DRIFT</td><td>1655</td><td>79.0%</td><td>76.4%</td><td><strong>+2.6pp</strong></td><td>⚠️ 观察（<strong>CI 跨 0</strong>；<strong>同价位口径下增量 edge 为 −0.4pp，即报告值几乎全是价位偏差</strong>）</td></tr><tr><td>SSS_VETO（定盘星背离族）</td><td>109</td><td>84.4%</td><td>75.3%</td><td><strong>+9.1pp</strong></td><td>✅ 已达 50 场判据线；10-21 口径下唯一统计显著；<strong>但 10-24 后连续 12 天单调退潮（+13.0→+9.1pp），且同价位口径下 10 月增量 edge 已归零</strong></td></tr><tr><td>A_UNDERDOG_QUAKE</td><td>39</td><td>61.5%</td><td>61.8%</td><td><strong>−0.3pp</strong></td><td>⏳ 39/50（<strong>全窗口为负</strong>；<strong>已被诊断出是 GLOBAL 的弱子集，n=39 是口径产物</strong>，见 §七）</td></tr></tbody></table><p><strong>影子轨（符号修正对照 · 纯观测）</strong>：</p><table tabindex="0"><thead><tr><th>信号</th><th>n</th><th>命中率</th><th>超额</th><th>判据进度</th></tr></thead><tbody><tr><td>SSS_VETO_H_FIX（2026-09-07 建轨）</td><td>112</td><td>85.7%</td><td><strong>+4.0pp</strong></td><td>⏳ <strong>已越过 50 场线（112/50）</strong>；到线后从 +8pp 一路降到 +3.0pp，近一周自低位回升到 +4.0pp；按建轨规则仍仅记账不裁决，是否收口待用户裁决</td></tr></tbody></table><p>样本变化趋势（自 08-21 冻结以来）：HOME 246→2611、GLOBAL 171→1655、VETO 15→109、QUAKE 80→39（注：QUAKE 是滚动窗口重切后重新累计，n 回落属正常——但 <strong>n=39 的真正原因不是&quot;样本没攒够&quot;，而是口径，见 §七</strong>）。</p><p><strong>读数方式</strong>（重要，避免误读）：</p><ul><li>两条 DRIFT（2611/1655 场）已是全场最大样本，超额稳定在 <strong>+3.2 / +2.6pp</strong>——<strong>&quot;样本变大、虚高退潮&quot;的迹象</strong>： 考决时的 +20pp 级超额大部分是回测乐观偏差，真实结构优势比想象的小。 <strong>但 10-21 的显著性检验把这两条的性质分开了</strong>：HOME 的置信区间稳定排除 0（真·稳定小 edge，但上界恰好压在 5pp 线上）； GLOBAL 的区间<strong>跨 0</strong>，且三个月逐月都跨 0 —— 它连&quot;edge 存在&quot;这一步都还没证成；</li><li><strong>VETO 的&quot;到线后退潮&quot;已经从&quot;震荡&quot;变成了&quot;下行&quot;</strong>：09-13 到线时 56 场 / 91.1% / <strong>+16.1pp</strong> → 09-27 65 场 / +12.3pp → 10-04 73 场 / +13.4pp → 10-18 88 场 / +12.3pp → 10-24 94 场 / <strong>+13.0pp</strong> → 10-27 101 场 / +11.9pp → 10-29 106 场 / +10.6pp → <strong>11-01 109 场 / 84.4% / +9.1pp</strong>。 10-18 至 10-24 那段&quot;回到原点&quot;曾被读成&quot;真实值就在 +12~13pp 附近&quot;；<strong>10-24 之后的 12 天把这句话证伪了</strong>—— 不是震荡，是<strong>连续下行，且每一段都在往下走</strong>。 但&quot;到线&quot;只等于<strong>具备谈转正的资格</strong>，不等于转正——转正是规则/定位层面的变更，须用户裁决并留预注册卷宗；</li><li><strong>QUAKE 全窗口为负（39 场 / 61.5% / −0.3pp）</strong>：四条里<strong>唯一超额为负</strong>的一条。 但 10-21 的诊断改变了这个问题的性质——<strong>它根本不该被当作&quot;样本不足待观察&quot;来处理</strong>（见 §七）。 若按判据走到 50 场仍为负，应进入处置讨论（<strong>需用户裁决，不自动执行</strong>）。</li></ul><blockquote><p>⚠️ <strong>上表所有&quot;超额&quot;列都是&quot;命中率 − 场均隐含概率&quot;这个朴素口径</strong>。 10-30 的诊断证明这个口径<strong>混入了价位校准偏差</strong>——详见 §八。<strong>读这张表时必须连着 §八 一起读。</strong></p></blockquote><h2 id="五、veto-h-的符号核实-一次-修-bug-会杀掉真-edge-的复盘-2026-09-07" tabindex="-1">五、VETO_H 的符号核实：一次&quot;修 bug 会杀掉真 edge&quot;的复盘（2026-09-07） <a class="header-anchor" href="#五、veto-h-的符号核实-一次-修-bug-会杀掉真-edge-的复盘-2026-09-07" aria-label="Permalink to &quot;五、VETO_H 的符号核实：一次&quot;修 bug 会杀掉真 edge&quot;的复盘（2026-09-07）&quot;">​</a></h2><p>一次外部代码审查指出：定盘星背离（VETO_H）的赔率位移计算里，<strong>传入的是去水后的概率而非原始赔率</strong>， 导致实际触发语义与文档宣称<strong>方向相反</strong>。核实结论如下（脱敏，仅列方法）：</p><ol><li><p><strong>Bug 属实</strong>：位移函数喂错了输入（该用原始赔率处用了去水概率），使实际计算量变成&quot;概率的对数位移&quot;； 因去水归一化会引入符号反转，<strong>实际 firing 语义 = 两家职业盘大位移背离下的&quot;锐钱回热&quot;</strong>， 与注释宣称的&quot;锐钱离场&quot;方向相反。</p></li><li><p><strong>但&quot;修复&quot;会杀掉唯一真 edge</strong>：按注释原意做对照回测（口径对齐 OOS），</p><table tabindex="0"><thead><tr><th>版本</th><th>n</th><th>命中率</th><th>超额</th></tr></thead><tbody><tr><td>现役版（实际计算）</td><td>52</td><td>90.4%</td><td><strong>+15.8pp</strong></td></tr><tr><td>文字原意版（&quot;修 bug&quot;后）</td><td>48</td><td>91.7%</td><td><strong>+9.2pp</strong></td></tr></tbody></table><p><strong>两版触发集完全不相交</strong>（数学必然：同一腿的 logP 降 ⟺ logOdds 升），且<strong>两个相反方向各自为正超额</strong>。</p></li><li><p><strong>处置（三条，均不改判定口径）</strong>：</p><ul><li>文档带日期<strong>勘误</strong>（不静默改写历史），并把&quot;禁止盲目修参&quot;写成代码注释；</li><li>摘除已处死的<strong>展示层方向标签</strong>（升级逻辑早在 08-21 考决被判负贡献，纯显示层，不进入统计）；</li><li>建<strong>独立影子轨</strong>并行取证——&quot;文字原意版&quot;作为对照信号持续记账，n≥50 前不参与任何裁决。</li></ul></li></ol><blockquote><p><strong>这条的价值不在&quot;抓到一个 bug&quot;，而在暴露了一种更危险的冲动：看到实现与注释不符就条件反射地&quot;修&quot;。</strong> 当实测 edge 归属于带 Bug 的实际计算时，Bug 是<strong>承重的</strong>——修掉它等于换了一个从未验证过的方向。 真正的判别特征也许根本不是&quot;方向&quot;，而是&quot;<strong>两家职业盘大位移背离 + 热门区错位定价</strong>&quot;这一类结构， 方向只是它的两个切面。edge 归属必须由数据裁决，不能由故事裁决。</p></blockquote><h2 id="六、候选过滤规则-未转正-观察中" tabindex="-1">六、候选过滤规则（未转正，观察中） <a class="header-anchor" href="#六、候选过滤规则-未转正-观察中" aria-label="Permalink to &quot;六、候选过滤规则（未转正，观察中）&quot;">​</a></h2><p>欧亚同向性观测（&quot;亚盘让球方 = 欧赔信号受益方&quot;为同向）：</p><table tabindex="0"><thead><tr><th>口径</th><th>同向</th><th>反向（冲突）</th><th>差值</th></tr></thead><tbody><tr><td>回测验证</td><td>83.0%</td><td>62.3%</td><td>+20.7pp</td></tr><tr><td>OOS 跟踪（截至 09-20）</td><td>83.5%（1978 场）</td><td>63.5%（315 场）</td><td>+20.0pp</td></tr><tr><td>OOS 跟踪（截至 09-27）</td><td>83.3%（2175 场）</td><td>63.7%（333 场）</td><td>+19.6pp</td></tr><tr><td>OOS 跟踪（截至 09-30）</td><td>83.7%（2299 场）</td><td>63.3%（354 场）</td><td><strong>+20.4pp</strong></td></tr><tr><td>OOS 跟踪（截至 10-18）</td><td>83.6%（3054 场）</td><td>62.8%（454 场）</td><td><strong>+20.8pp</strong></td></tr></tbody></table><p>OOS 与回测基本一致（差值稳定在 +20pp 附近，样本从 2293 场增至 3508 场仍稳定，且<strong>反向样本从 315 涨到 454 场</strong>）——若维持， 则&quot;欧亚方向冲突的场次信号不可信&quot;可成候选过滤规则。<strong>当前仅为观测，未改任何信号规则。</strong></p><blockquote><p>补充（2026-10-23 读数）：同向 83.6% vs 反向 62.9%，差 <strong>+20.7pp</strong>，与上表口径一致。 该日<strong>未逐场记录分项场次</strong>，故不单列一行——<strong>本系列不为凑表格而补 n</strong>； 一行缺 n 的百分比，比不写这一行更危险。</p></blockquote><h2 id="七、统计显著性-把-稳-和-显著-分开-2026-10-21" tabindex="-1">七、统计显著性：把&quot;稳&quot;和&quot;显著&quot;分开（2026-10-21） <a class="header-anchor" href="#七、统计显著性-把-稳-和-显著-分开-2026-10-21" aria-label="Permalink to &quot;七、统计显著性：把&quot;稳&quot;和&quot;显著&quot;分开（2026-10-21）&quot;">​</a></h2><p>到 10-18 为止，四信号的读数看上去是&quot;两条大的稳、一条强的回落、一条小的转负&quot;。 但&quot;稳&quot;是一个<strong>叙事</strong>，不是检验结果。10-21 做了一轮完整的显著性检验，<strong>结论比数字本身更重要</strong>。</p><p><strong>方法</strong>：全量口径下按二项近似算标准误；再用<strong>聚类 bootstrap</strong>（按日 / 按联赛，1000 次重采样，固定种子可复现） 检验&quot;同日同联赛的相关性&quot;会不会改变结论。样本基数：有效信号场 3,692（10-21 口径）。</p><table tabindex="0"><thead><tr><th>信号</th><th>超额</th><th>朴素 95% CI</th><th>按日聚类 CI</th><th>按联赛聚类 CI</th><th>判定</th></tr></thead><tbody><tr><td>SSS_VETO</td><td>+13.0pp</td><td>[+6.4, +19.6]</td><td>[+7.2, +19.1]</td><td>[+5.8, +19.6]</td><td>✅ <strong>统计显著</strong>，两条路径下界均 &gt;5pp</td></tr><tr><td>SSS_HOME_DRIFT</td><td>+3.4pp</td><td>[+1.8, +5.0]</td><td>[+1.7, +5.0]</td><td>[+1.9, +4.7]</td><td>⚠️ 稳定排除 0，但<strong>上界恰好压在 5pp 线上</strong></td></tr><tr><td>SSS_GLOBAL_DRIFT</td><td>+2.2pp</td><td>[−0.1, +4.2]</td><td>[+0.1, +3.7]</td><td>[−0.1, +4.1]</td><td>⚠️ <strong>跨 0</strong>——&quot;edge 极弱且未能在任一分月稳定复现&quot;</td></tr><tr><td>A_UNDERDOG_QUAKE</td><td>−0.9pp</td><td>各区间全跨 0</td><td>—</td><td>—</td><td>⏳ 统计上不能证明有 edge，也不能证明无</td></tr></tbody></table><p><strong>这张表推翻了三个此前的读法</strong>：</p><ol><li><strong>&quot;GLOBAL 差 1.5pp 就到 5pp 门槛&quot;是错的。</strong> 它的区间跨 0，且<strong>三个月逐月都跨 0</strong> （08 月 [−1.1, +6.3]、09 月 [−0.9, +5.7]、10 月 [−3.7, +5.2]）。 10 月那个 +0.8pp 不是&quot;退坡&quot;，而是<strong>同一状态的延续</strong>。 正确表述是：<strong>尚未证实它有 edge</strong>——这和&quot;有 edge 但不够大&quot;是两件事，而报告里两者用的是同一个 ⚠️ 标签。</li><li><strong>VETO 的显著性是真的。</strong> 全量 +13.0pp、10 月 +14.3pp（CI [+2.1, +26.6]）都排除 0； 9 月那个 +7.5pp 跨 0，属 n=26 的小样本噪声，<strong>不构成&quot;衰减&quot;的证据</strong>。 但要留一句：按联赛聚类的下界是 +5.8pp，<strong>距 5pp 线只有 0.8pp 缓冲</strong>——不宜当定论。</li><li><strong>HOME 是唯一&quot;稳定但不达标&quot;的一条。</strong> 三个月分别 +2.8 / +4.1 / +3.1pp， 全量 CI 稳定排除 0——方向是稳的，问题只是<strong>幅度不够</strong>。</li></ol><p><strong>一处必须自我更正的地方</strong>：上一轮曾推测&quot;同日同联赛存在相关性 → 聚类修正后 CI 只会更宽&quot;。 实测<strong>是错的</strong>——设计效应只有 0.77~1.12 倍，CI 宽度基本不变，按日聚类甚至更窄。 <strong>&quot;聚类一定会放大方差&quot;不是定理，是直觉</strong>；这次直觉输了。 保留的怀疑：设计效应 &lt;1 也可能说明 bootstrap 低估了方差（簇内样本小、轻微负相关），故不宜把 CI 读得比它看起来更窄。</p><p><strong>顺带查了两个数据质量假设，都被证伪</strong>：</p><ul><li><strong>隐含概率被&quot;填 0&quot;导致超额虚高</strong>：3,692 条里只有 <strong>1 条</strong>为 null（0.03%）， 剔除后四信号超额差<strong>均为 0.0pp</strong> → <strong>无污染</strong>，上述结论不受影响。 但&quot;缺值按 0 计&quot;仍是一个真实脆弱点（未来赔率大面积抓取失败会静默虚增），建议改为跳过并计数，属代码改动待批；</li><li><strong>&quot;方向冲突熔断 5 场被排除在统计外&quot;</strong>：报告措辞是&quot;空仓避险&quot;，但实测这 5 场<strong>仍在各信号的 n 之内</strong>—— <strong>措辞与口径不符</strong>。剔除后影响极小（VETO +13.0→+13.4pp、GLOBAL +2.0→+2.1pp、HOME/QUAKE 不变、合并 +3.10→+3.11pp）， 故建议<strong>只改措辞、不改统计</strong>（改逻辑要重算全部历史口径）。</li></ul><p><strong>由此暴露一个判据档位的缺口（待用户批准）</strong>：现有报告只有&quot;转正候选 / 观察 / 待观察&quot;三档， <strong>没有&quot;统计不显著&quot;这一档</strong>，于是 GLOBAL 和 HOME 拿到了同一个 ⚠️ 标签—— 一个&quot;稳但不够大&quot;，一个&quot;连存在性都没证成&quot;。<strong>这不是数字错了，是标签把两种不同的事说成了同一种。</strong> 本轮共提了 5 项变更提案（判据加&quot;统计不显著&quot;档 / 报告文件名日期口径 / 缺值处理 / 熔断措辞 / QUAKE 归属）， <strong>全部未应用</strong>，等用户拍板。</p><h3 id="quake-的-n-33-样本不足-是个伪问题" tabindex="-1">QUAKE 的&quot;n=33 样本不足&quot;是个伪问题 <a class="header-anchor" href="#quake-的-n-33-样本不足-是个伪问题" aria-label="Permalink to &quot;QUAKE 的&quot;n=33 样本不足&quot;是个伪问题&quot;">​</a></h3><p>这是本轮最反直觉的一条。QUAKE 长期显示 33/50，看上去是&quot;样本攒得慢&quot;。实测：</p><table tabindex="0"><thead><tr><th>口径</th><th>n</th><th>命中率</th></tr></thead><tbody><tr><td>真实触发（无条件）</td><td><strong>246</strong></td><td>71.1%</td></tr><tr><td>被其他信号吸收（不计入）</td><td>213（占 86.6%）</td><td>72.8%</td></tr><tr><td><strong>独占触发（当前统计口径）</strong></td><td><strong>33</strong></td><td><strong>60.6%</strong></td></tr></tbody></table><p><strong>根因是口径而非样本</strong>：对账脚本对每场只取<strong>首个匹配</strong>的信号，优先级顺序把 QUAKE 排在最后 → 它只统计&quot;独占触发&quot;的那一小撮。按这个口径，<strong>&quot;攒到 50 场&quot;在结构上极难达成</strong>（独占率 13.4%，近 10 天独占 0 场）。</p><p>更关键的是第二层：那 213 场被吸收的样本，<strong>100% 归给了 GLOBAL 的客向分支</strong>，与其余两信号零共现、方向冲突 0 场。 也就是说 <strong>QUAKE 的触发集只有两种形态：单独出现，或作为 GLOBAL 的一部分出现</strong>—— <strong>它是 GLOBAL 的一个弱子集，不是一个独立信号。</strong></p><p>而&quot;独占子集 60.6% 反而比被吸收子集 72.8% 更差&quot;这件事，指向一个更麻烦的结论： <strong>表面上 71.1% 的命中率，是借了共现信号的 edge，不是 QUAKE 自己的。</strong> 独占子集三个月分段 62.5% / 58.3% / 60.0%，<strong>稳定贴在盈亏平衡线 61.5% 附近</strong>——稳定地没有 edge。</p><blockquote><p>处置建议（<strong>未执行</strong>）：把 QUAKE 从&quot;独立判据名单&quot;降级为&quot;GLOBAL 的弱子集&quot;，移出判据线； <strong>不处决</strong>（n=33 &lt; 50，按纪律不到处决线）。这条改动会影响&quot;四信号&quot;这个对外说法， 属定位层面的变更，须用户裁决 + 留卷宗。 <strong>一个曾被提出又主动撤回的方案</strong>：给它单开一条&quot;无条件影子轨&quot;。撤回原因很直接—— 246 场里 213 场就是 GLOBAL，单开等于<strong>把同一批样本重复计价一次</strong>，会凭空制造一个看起来样本充足的假信号。</p></blockquote><h2 id="八、扣掉价位偏差之后-四条信号的-增量-edge-全部归零-2026-10-30" tabindex="-1">八、扣掉价位偏差之后：四条信号的&quot;增量 edge&quot;全部归零（2026-10-30） <a class="header-anchor" href="#八、扣掉价位偏差之后-四条信号的-增量-edge-全部归零-2026-10-30" aria-label="Permalink to &quot;八、扣掉价位偏差之后：四条信号的&quot;增量 edge&quot;全部归零（2026-10-30）&quot;">​</a></h2><h3 id="起因-一个从未被检验的口径假设" tabindex="-1">起因：一个从未被检验的口径假设 <a class="header-anchor" href="#起因-一个从未被检验的口径假设" aria-label="Permalink to &quot;起因：一个从未被检验的口径假设&quot;">​</a></h3><p>&quot;超额 = 命中率 − 场均隐含概率&quot;这个公式里藏着一个假设： <strong>信号的样本，其隐含概率分布与市场平均一致。</strong> 如果不一致，这个差值里就混进了两样东西—— ①信号比市场多知道的信息（真 edge）；②<strong>信号挑选的样本本身赔率就偏高或偏低</strong>（价位偏差）。</p><p>VETO 明显不满足这个假设：它挑的是<strong>隐含概率约 75% 的高价客队</strong>，而全市场平均隐含只有 ~58%。 拿 75% 的样本去比 58% 的基准，差出来的 17pp 里有多少是信号本事、多少只是&quot;高价客队本来就更常不败&quot;？ <strong>这个公式回答不了。</strong></p><h3 id="第一次自我更正-基线选错了" tabindex="-1">第一次自我更正：基线选错了 <a class="header-anchor" href="#第一次自我更正-基线选错了" aria-label="Permalink to &quot;第一次自我更正：基线选错了&quot;">​</a></h3><p>第一版直接拿&quot;全市场客不败率&quot;当基线，得出&quot;10 月 VETO 大幅失效&quot;。<strong>这是错的</strong>—— 它把&quot;VETO 专挑高价场&quot;和&quot;高价场更常不败&quot;混成了一件坏事。 改成<strong>同价位对照</strong>：只看隐含概率落在同一档（70~80%）的全市场场次，它们的命中率是多少。</p><table tabindex="0"><thead><tr><th>月份</th><th>同档（隐含 70~80%）全市场命中</th><th>VETO 相对该档的 edge</th></tr></thead><tbody><tr><td>08 月</td><td>78.9%</td><td><strong>+12.0pp</strong></td></tr><tr><td>09 月</td><td>76.8%</td><td><strong>+8.1pp</strong></td></tr><tr><td>10 月</td><td><strong>80.1%（三个月最优）</strong></td><td><strong>−1.8pp</strong></td></tr></tbody></table><p><strong>这个更正把结论从&quot;VETO 全面失效&quot;改成了&quot;VETO 在 10 月相对同价位市场失效&quot;</strong>—— 市场自己在 10 月对高价客队的定价变准了，VETO 没有跟上。 顺带排除了一个解释：VETO 的杯赛占比从 41.5% 升到 51.2%，但<strong>联赛与杯赛两条腿同步下滑</strong>， 所以不是&quot;赛事类型变了&quot;。</p><h3 id="体系级-四条信号逐场匹配基线" tabindex="-1">体系级：四条信号逐场匹配基线 <a class="header-anchor" href="#体系级-四条信号逐场匹配基线" aria-label="Permalink to &quot;体系级：四条信号逐场匹配基线&quot;">​</a></h3><p>把方法推到全部四条：<strong>每场只跟&quot;该场隐含概率 ±1pp 档内的全市场命中率&quot;比</strong>（n&lt;50 的档对称扩档）， 让每个样本的基准都落在它自己那个价位上。</p><table tabindex="0"><thead><tr><th>信号</th><th>报告超额（朴素口径）</th><th>扣掉价位偏差后</th><th>差额 = 价位偏差</th></tr></thead><tbody><tr><td>SSS_VETO</td><td>+13.0pp（10-24 口径）</td><td><strong>+5.7pp</strong>（08 +12.2 / 09 +4.4 / <strong>10 +0.1</strong>）</td><td>约 7pp</td></tr><tr><td>SSS_HOME_DRIFT</td><td>+3.0pp</td><td><strong>+0.9pp</strong></td><td><strong>约 2.1pp</strong></td></tr><tr><td>SSS_GLOBAL_DRIFT</td><td>+2.8pp</td><td><strong>−0.4pp</strong></td><td><strong>约 3.2pp（即全部）</strong></td></tr><tr><td>A_UNDERDOG_QUAKE</td><td>−1.3pp</td><td><strong>−3.2pp</strong></td><td>反向</td></tr></tbody></table><p><strong>这张表把&quot;四条信号都有 edge，只是大小不同&quot;改写成了&quot;扣掉价位偏差后，没有一条有可信的增量 edge&quot;。</strong></p><ul><li>HOME 那个&quot;稳定排除 0 的 +3.2pp&quot;，有约 <strong>2.1pp</strong> 来自&quot;它专挑隐含 79% 的场次&quot;这个事实；</li><li><strong>GLOBAL 的 +2.6pp 几乎全部是价位偏差</strong>，扣完只剩 −0.4pp —— 这与 10-21 那个&quot;CI 跨 0&quot;的结论<strong>互相印证</strong>， 两条独立路径指向同一件事；</li><li>VETO 是唯一扣完还剩正数的（+5.7pp），<strong>但它的正数几乎全在 8 月</strong>：08 +12.2 → 09 +4.4 → <strong>10 +0.1</strong>。 这条曲线比任何&quot;n 不够&quot;的解释都更直接：<strong>有效性在逐月衰减，10 月已经贴到零。</strong></li></ul><h3 id="必须写清楚的局限" tabindex="-1">必须写清楚的局限 <a class="header-anchor" href="#必须写清楚的局限" aria-label="Permalink to &quot;必须写清楚的局限&quot;">​</a></h3><ul><li>只控了<strong>价格</strong>，没控<strong>联赛 / 球队强度</strong>。同价位不同联赛的市场命中率可能不同，这层没扣；</li><li>基线<strong>包含信号自身场次</strong>（&lt;0.5%），没做 leave-one-out，会让 edge 被自己略微拉高；</li><li>与 10-21 聚类检验的差异属<strong>口径之争</strong>：那边问&quot;这个数是不是 0&quot;，这边问&quot;这个数里有多少是价格带来的&quot;。 两个问题都合法、答案不冲突，<strong>但报告里只能有一个&quot;超额&quot;列</strong>——这才是真正的麻烦。</li></ul><blockquote><p><strong>处置（全部未应用）</strong>：①报告加&quot;近 50/30 场超额&quot;列（纯展示，推荐先做）； ②加&quot;同价位增量 edge&quot;列（需基线扫描 + 缓存，工程量大）； ③判据加&quot;统计不显著 / 近期失效&quot;两档（属规则改动，须拍板）。 <strong>明确不做</strong>：按隐含档 / 联赛 / 赛事类型加过滤——每档 n≤30，必然过拟合。 诊断到此收手，不改代码。</p></blockquote><h3 id="附-这一轮的三次自我更正-比结论更值得记" tabindex="-1">附：这一轮的三次自我更正（比结论更值得记） <a class="header-anchor" href="#附-这一轮的三次自我更正-比结论更值得记" aria-label="Permalink to &quot;附：这一轮的三次自我更正（比结论更值得记）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>次序</th><th>先说过的</th><th>实际</th><th>为什么错</th></tr></thead><tbody><tr><td>1</td><td>&quot;VETO 10 月全面失效&quot;</td><td>只在<strong>相对同价位市场</strong>时失效</td><td>基线拿错：拿全市场平均去比一个专挑高价场的信号</td></tr><tr><td>2</td><td>&quot;近 7 日已证失效（−15.1pp）&quot;</td><td><strong>不显著</strong>：近 7 日 9/15，Wilson 区间 [35.7, 80.2]，覆盖隐含 75%</td><td>把点估计当结论，没给区间</td></tr><tr><td>3</td><td>&quot;衰减不是抖动，是结构&quot;</td><td>衰减成立，但<strong>证据只有两条</strong>：①逐月单调 ②两比例检验（z=−2.52 / p=0.0116，且切点事后选的，p 要打折）</td><td>证据强度说高了</td></tr></tbody></table><p>第 2 条尤其值得记：<strong>&quot;近 7 日 −15.1pp&quot;听起来像铁证，但 n=15、9 次命中，置信区间宽到能装下结论的反面。</strong> 点估计的绝对值越大，越容易被当成证据——<strong>而样本越小，点估计越容易大。</strong></p><p>第 3 条之后又补了一刀：<strong>&quot;数据质量变差&quot;这个假设被证伪了</strong>。 近期段的公司数均值是四段里最高的（18.1 → 18.4 → 19.9 → <strong>21.0</strong>），没有赔率缺失、取数时点齐全。 真正的线索是<strong>触发时的背离强度本身在变弱</strong>：位移量均值逐段单调减弱（−0.212 → −0.171 → −0.149 → <strong>−0.121</strong>）。 也就是说，<strong>不是数据变差了，是输入变弱了</strong>——信号还在按规则触发，但每次触发所依据的&quot;分歧&quot;越来越浅。</p><blockquote><p>这一节最大的产出不是&quot;发现 VETO 失效了&quot;，而是&quot;<strong>发现自己三次把话说过了头</strong>&quot;。 三次方向完全一致：<strong>都把点估计当成了结论。</strong></p></blockquote><hr><blockquote><p>结论（截至 2026-11-01）：V5 四信号<strong>无一判死</strong>，但它们的&quot;性质&quot;这一轮又被改写了一层—— 从&quot;数字高低不同&quot;到&quot;显著性不同&quot;，再到**&quot;扣掉价位偏差后都没有可信增量 edge&quot;<strong>。 <strong>VETO 仍在退潮</strong>（109 场 / 84.4% / <strong>+9.1pp</strong>）：到线时 56 场 / +16.1pp → 10-24 94 场 / +13.0pp → <strong>11-01 109 场 / +9.1pp</strong>，10-24 之后是</strong>连续 12 天单调下行**，不再是&quot;围绕某个值震荡&quot;； 且同价位口径下 <strong>10 月增量 edge 只有 +0.1pp</strong>（08 +12.2 / 09 +4.4 / 10 +0.1）。 <strong>HOME 稳定但不达标</strong>（2611 场 / +3.2pp，区间排除 0、上界压在 5pp，同价位口径仅 +0.9pp）； <strong>GLOBAL 的 +2.6pp 几乎全是价位偏差</strong>（同价位 −0.4pp），与&quot;区间跨 0&quot;互相印证； <strong>QUAKE 已被诊断出是 GLOBAL 的弱子集</strong>（39 场 / −0.3pp，全窗口为负，n=39 是口径产物）。 一句话：<strong>&quot;到线之后&quot;数字并没有变得更好；&quot;样本不够&quot;在 QUAKE 身上不成立； 而&quot;超额为正&quot;这件事本身，可能主要是价位偏差。</strong> 影子轨（符号修正对照）越过 50 场线后（112 场 / 85.7% / +4.0pp）从 +8pp 一路降到 +3.0pp、近一周回升到 +4.0pp， 按建轨规则仍仅记账不裁决，<strong>是否收口须用户裁决并留预注册卷宗</strong>。 <strong>全部信号仍在观察期，无一转正。</strong></p></blockquote><p><a href="/足球信号雷达/">返回 足球信号雷达 首页</a></p>',72)]))}const i=o(s,[["render",g]]);export{l as __pageData,i as default};
